import React from 'react';
import { useNavigate } from 'react-router-dom';

// Import SCSS
import './importance-blocks.scss';

const ImportanceMatrix = () => {
    const navigate = useNavigate();

    const handleMatrixButtonClick = () => {
        navigate('/matrix');
      };

    return (
        <div className="container importance-blocks" id="why-know-matrix">
            <section className="importance-matrix">
                <div className="importance-content">
                    <div className="importance-left">
                        <div className="importance-header">
                            <h2>
                                Зачем нам знать <br />
                                <span className="highlight">Матрицу судьбы</span> ?
                            </h2>
                        </div>
                        <div className="importance-image">
                            <img src={process.env.PUBLIC_URL + "/assets/img/Impotance-matrix/matrix-preview.png"} alt="Матрица судьбы" />
                        </div>
                    </div>
                    <div className="importance-right">
                        <div className="importance-text">
                            <ul>
                                <li className="importance-text_red">Матрица судьбы расскажет о ваших сильных сторонах, о предназначении и талантах, через что к вам приходят деньги</li>
                                <li className="importance-text_orange">Узнав свою Матрицу, поймете, где появляются трудности и почему не получается изменить свою жизнь в лучшую сторону</li>
                                <li className="importance-text_green">Поймете, что надо делать, чтобы наладить отношения с собой, детьми, родителями, партнерами</li>
                                <li className="importance-text_blue">Сможете лучше понимать своих близких</li>
                                <li className="importance-text_purple">С помощью калькулятора совместимости узнаете как наладить отношения со своей второй половинкой и вдохнуть в вашу жизнь новые эмоции</li>
                            </ul>
                        </div>
                    </div>
                </div>
                <div className="importance-button">
                    <button className="tab" onClick={handleMatrixButtonClick}>
                        Рассчитать Матрицу Судьбы
                    </button>
                </div>
            </section>
        </div>
    );
};

export default ImportanceMatrix;
