import React, { useState } from 'react';

// Import SCSS
import './how-it-work.scss';

const HowItWorks = () => {
    const [activeTab, setActiveTab] = useState('calculation');

    // Функция для изменения активной вкладки
    const handleTabClick = (tabName) => {
        setActiveTab(tabName);
    };

    return (
        <div className="container how-it-works" id="how-it-works">
            <section className="how-it-works-section">
                <div className="how-it-works_title">
                    <h2>Как работает <span className="highlight">Матрица Судьбы</span> ?</h2>
                </div>

                <div className="tab-buttons">
                    <button
                        className={`tab ${activeTab === 'calculation' ? 'active' : ''}`}
                        onClick={() => handleTabClick('calculation')}
                    >
                        Расчет
                    </button>
                    <button
                        className={`tab ${activeTab === 'analysis' ? 'active' : ''}`}
                        onClick={() => handleTabClick('analysis')}
                    >
                        Анализ
                    </button>
                    <button
                        className={`tab ${activeTab === 'interpretation' ? 'active' : ''}`}
                        onClick={() => handleTabClick('interpretation')}
                    >
                        Интерпретация
                    </button>
                </div>

                <div className="tab-content">
                    {activeTab === 'calculation' && (
                        <div id="calculation">
                            <h3>Этап Расчета</h3>
                            <p>На этом этапе производится расчет вашей матрицы на основе введенных данных. Используются сложные алгоритмы, которые анализируют вашу дату рождения и другие личные данные, чтобы создать уникальную матрицу.</p>
                            <ul>
                                <li>Ввод исходных данных</li>
                                <li>Применение расчетных алгоритмов</li>
                                <li>Получение начальных значений матрицы</li>
                            </ul>
                        </div>
                    )}

                    {activeTab === 'analysis' && (
                        <div id="analysis">
                            <h3>Этап Анализа</h3>
                            <p>Анализ включает в себя исследование всех аспектов вашей матрицы. Вы узнаете, как разные элементы взаимодействуют между собой и как это влияет на вашу жизнь и судьбу.</p>
                            <ul>
                                <li>Анализ взаимодействия элементов</li>
                                <li>Определение ключевых точек судьбы</li>
                                <li>Выявление скрытых возможностей и угроз</li>
                            </ul>
                        </div>
                    )}

                    {activeTab === 'interpretation' && (
                        <div id="interpretation">
                            <h3>Этап Интерпретации</h3>
                            <p>На этом этапе вам будет предоставлена подробная интерпретация всех аспектов вашей матрицы. Вы поймете свои сильные и слабые стороны, а также получите рекомендации по улучшению своей жизни.</p>
                            <ul>
                                <li>Интерпретация сильных сторон</li>
                                <li>Выявление жизненных уроков</li>
                                <li>Рекомендации по улучшению</li>
                            </ul>
                        </div>
                    )}
                </div>
            </section>
        </div>
    );
};

export default HowItWorks;