import React from 'react';

// Import SCSS
import './InfoBlocks.scss';

const infoBlocksData = [
  {
    title: "Матрица Судьбы:",
    description: "Это уникальная методика, которая позволяет глубже понять свое предназначение, внутренние ресурсы и возможности. С ее помощью можно осознать свои сильные и слабые стороны, а также найти оптимальные пути для достижения личных целей и гармонии в жизни.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/Matrix.webp",
    alt: "Матрица Судьбы"
  },
  {
    title: "Финансовая Матрица:",
    description: "Предназначена для анализа ваших финансовых возможностей и потенциала. Она помогает определить наиболее выгодные направления для инвестиций, понять, как лучше управлять своими денежными потоками и добиться финансовой стабильности и независимости.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/FinanceMatrix.webp",
    alt: "Финансовая Матрица"
  },
  {
    title: "Матрица Совместимость:",
    description: "Помогает определить уровень гармонии и понимания между партнерами. С ее помощью можно выяснить, какие аспекты отношений требуют внимания и улучшения, а также найти пути для укрепления взаимопонимания и любви в паре.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/Compatibility-Matrix.webp",
    alt: "Матрица Совместимость"
  },
  {
    title: "Детская Матрица:",
    description: "Помогает родителям лучше понять потенциал и способности своего ребенка. Она раскрывает особенности характера, склонности и таланты, что позволяет создать оптимальные условия для развития и воспитания, а также поддержать ребенка на его жизненном пути.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/Child-Matrix.webp",
    alt: "Детская Матрица"
  },
  {
    title: "Карьерная Матрица:",
    description: "Карьерная Матрица помогает выявить ваши профессиональные сильные и слабые стороны, а также определить оптимальные пути карьерного роста. С ее помощью можно понять, какие навыки нужно развивать для достижения успеха в выбранной профессии.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/Career-Matrix.webp",
    alt: "Карьерная Матрица"
  },
  {
    title: "Здоровье и Благополучие:",
    description: "Матрица Здоровья и Благополучия помогает понять, как энергетика вашего тела и ума влияет на общее самочувствие. Она предлагает советы по улучшению физического и психического здоровья через анализ ваших личных энергий.",
    image: process.env.PUBLIC_URL + "/assets/img/info-block_image/Health-Matrix.webp",
    alt: "Здоровье и Благополучие"
  }
];

const InfoBlock = ({ title, description, image, alt }) => (
  <section className="info-block">
    <div className="info-content">
      <h2>{title}</h2>
      <p>{description}</p>
    </div>
    <div className="info-image">
      <img src={image} alt={alt} />
    </div>
  </section>
);

const InfoBlocks = () => {
  return (
    <div className="container info-blocks" id="about">
      {infoBlocksData.map((block, index) => (
        <InfoBlock key={index} {...block} />
      ))}
    </div>
  );
};

export default InfoBlocks;